5	import {
6	  MS_PER_AVG_MONTH,
7	  prorateDeltaCents,
8	  prorateUpgradeCents,
9	  prorateDowngradeCreditCents,
10	  remainingMonths,
11	} from "../lib/proration.ts";
12	import { vpsTermPriceCents } from "../lib/billing-terms.ts";
13	import { currentPromo, promoPriceCents, LAUNCH_SALE, type Promo } from "../lib/promotions.ts";
14	
15	/**
16	 * REAL INCIDENTS — docs/QA-PRELAUNCH.md P0-6 (and its mirror image):
17	 *
18	 *  1. Upgrade proration priced the RAW list-price monthly delta while the original
19	 *     order applied both the term discount and the seasonal promo. On a 36-month
20	 *     term with the 30% Summer Sale running, upgrading Starter -> Max the day after
21	 *     purchase cost $1,044.45 against $665.08 for buying Max outright on the same
22	 *     end date: the customer overpaid $379.37.
23	 *  2. The downgrade CREDIT used that same undiscounted delta, so it refunded more
24	 *     than had ever been paid — a self-service money printer that was one
25	 *     cheap-but-storage-heavy plan away from reachable (blocked today only by the
26	 *     disk-monotonic guard, QA P1-14).
27	 *  3. The fix for (2) also CAPPED the credit's duration at one term while the
28	 *     charge side kept pricing every remaining month, which broke the round trip in
29	 *     the other direction. A customer whose stacked "Renew now" had pushed
30	 *     `expiresAt` 36 months out on a 12-month term paid $544.32 to go
31	 *     Starter -> Max and got $181.44 back coming straight down: the platform kept
32	 *     $362.88 of months they had paid for. `remainingMonths` no longer takes a cap
33	 *     at all, so the two directions cannot express different durations.
34	 *
35	 * Both directions now price through lib/proration.ts. These tests hold the two
36	 * halves against each other so they cannot drift apart again.
37	 *
38	 * Deterministic: every `now` and every promo is injected — nothing reads the clock
39	 * except through a value supplied by the test.
40	 */
41	
42	/** Live plan catalogue (cents/month) at the time of the incident. */
43	const STARTER = 899;
44	const MAX = 3299;
45	const TERM = 36;
46	
47	/** The 30% Summer Sale — the promo running when P0-6 was measured. */
48	const PROMO = currentPromo(new Date("2026-07-26T12:00:00.000Z"));
49	const NO_PROMO: Promo = { ...LAUNCH_SALE, discountPercent: 0 };
50	
51	/** What a FRESH order for `monthly` over `TERM` costs today (lib/order.ts). */
52	const freshOrderCents = (monthly: number, promo: Promo) =>
53	  promoPriceCents(vpsTermPriceCents(monthly, TERM), promo);
54	
55	test("the promo and catalogue this file is pinned to have not moved", () => {
56	  assert.equal(PROMO.discountPercent, 30);
57	  assert.equal(freshOrderCents(STARTER, PROMO), 18124, "Starter, 36mo, -20% term, -30% promo");
58	  assert.equal(freshOrderCents(MAX, PROMO), 66508, "Max, 36mo, -20% term, -30% promo");
59	});
60	
61	test("upgrading on day one costs exactly the difference between the two fresh orders", () => {
62	  // The invariant P0-6 broke: an upgrade must never cost more than simply having
63	  // bought the target plan for the same term in the first place.
64	  const charge = prorateUpgradeCents({
65	    fromMonthlyCents: STARTER,
66	    toMonthlyCents: MAX,
67	    termMonths: TERM,
68	    monthsRemaining: TERM,
69	    promo: PROMO,
70	  });
71	  assert.equal(charge, 48384);
72	  assert.equal(
73	    freshOrderCents(STARTER, PROMO) + charge,
74	    freshOrderCents(MAX, PROMO),
75	    "paid-for-Starter + upgrade must equal the price of Max bought outright",
76	  );
77	});
78	
79	test("a 36-month term with a promo does not reproduce the $379 overcharge", () => {
80	  // The old line was: monthlyDelta (raw list) x remainingMonths, with no term
81	  // discount and no promo. Reproduced here purely to measure the gap it created.
82	  const now = new Date("2026-07-27T12:00:00.000Z"); // bought yesterday
83	  const expiresAt = new Date("2029-07-26T12:00:00.000Z"); // 36-month term
84	  const months = remainingMonths(expiresAt, now.getTime());
85	  assert.ok(months > 35.9 && months < 36, `~36 months left, got ${months}`);
86	
87	  const oldOvercharge = Math.round((MAX - STARTER) * months); // the P0-6 formula
88	  const nowCharge = prorateUpgradeCents({
89	    fromMonthlyCents: STARTER,
90	    toMonthlyCents: MAX,
91	    termMonths: TERM,
92	    monthsRemaining: months,
93	    promo: PROMO,
94	  });
95	
96	  const paidTotalOld = freshOrderCents(STARTER, PROMO) + oldOvercharge;
97	  const paidTotalNow = freshOrderCents(STARTER, PROMO) + nowCharge;
98	  const fresh = freshOrderCents(MAX, PROMO);
99	
100	  assert.ok(paidTotalOld - fresh > 37_000, `the old formula overcharged by ${(paidTotalOld - fresh) / 100} USD`);
101	  // The corrected charge tracks the fresh price to within one day of elapsed term.
102	  assert.ok(
103	    fresh - paidTotalNow >= 0 && fresh - paidTotalNow <= 100,
104	    `upgrade must not exceed the fresh price; gap was ${fresh - paidTotalNow}c`,
105	  );
106	});
