192	test("a downgrade credit never exceeds what was paid, however many terms are stacked", () => {
193	  // This test used to bound a 108-month credit against ONE term's payment and
194	  // conclude that the uncapped figure was "free money". That is the wrong
195	  // denominator, and believing it is what justified capping the credit at one term
196	  // while the upgrade path charged for all 108 — the $362.88 asymmetry below.
197	  //
198	  // `expiresAt` only moves forward in exchange for payment: renewNow and the
199	  // auto-renew sweep each advance it by termMonths and charge vpsTermPriceCents for
200	  // exactly those months. So a customer sitting 108 months out on a 36-month term
201	  // has paid THREE terms, and the honest bound is per-month, not per-term.
202	  const now = new Date("2026-07-26T00:00:00.000Z").getTime();
203	  for (const stackedMonths of [36, 72, 108]) {
204	    const months = remainingMonths(new Date(now + stackedMonths * MS_PER_AVG_MONTH), now);
205	
206	    // What those months actually cost. The renewal paths charge the term-discounted
207	    // price with NO promo applied, so this is the real cash the customer handed over
208	    // per remaining month on Max.
209	    const paidPerMonth = vpsTermPriceCents(MAX, TERM) / TERM;
210	    const paidForMonths = paidPerMonth * months;
211	
212	    const credit = prorateDowngradeCreditCents({
213	      fromMonthlyCents: MAX,
214	      toMonthlyCents: STARTER,
215	      termMonths: TERM,
216	      monthsRemaining: months,
217	      promo: PROMO,
218	    });
219	    assert.ok(credit > 0, "the credit must actually move money, or this proves nothing");
220	    assert.ok(
221	      credit < paidForMonths,
222	      `${stackedMonths}mo stacked: credit ${credit} must stay under the ${Math.round(paidForMonths)} paid`,
223	    );
224	    // The bound holds structurally, not by luck: the credit is the DIFFERENCE between
225	    // two positive effective rates, so it is strictly less than the old plan's rate
226	    // over the same months no matter how many months there are. It holds with no
227	    // promo running too, which is the worst case for the platform.
228	    const undiscounted = prorateDowngradeCreditCents({
229	      fromMonthlyCents: MAX,
230	      toMonthlyCents: STARTER,
231	      termMonths: TERM,
232	      monthsRemaining: months,
233	      promo: NO_PROMO,
234	    });
235	    assert.ok(
236	      undiscounted < paidForMonths,
237	      `${stackedMonths}mo stacked, no promo: credit ${undiscounted} vs ${Math.round(paidForMonths)} paid`,
238	    );
