1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser } from "./auth";
6	// Re-exporting a const from a "use server" file is illegal (Next throws
7	// "found object"), so the choices live in a plain module.
8	import { BACKUP_INTERVAL_CHOICES } from "./backup-intervals";
9	import { prorateDowngradeCreditCents, remainingMonths } from "./proration";
10	
11	/**
12	 * Server lifecycle "extras" — scheduled backups, reinstall-to-a-different-OS and
13	 * resize-down. These complement the primary flows in `lib/actions-server.ts`
14	 * (create backup, resize-up, reinstall-same-OS). Every op is ownership-checked
15	 * and respects the "one in-flight job per server" invariant.
16	 */
17	
18	async function ownedServer(serverId: string) {
19	  const user = await requireUser();
20	  const server = await db.server.findUnique({
21	    where: { id: serverId },
22	    include: { plan: true, osTemplate: true },
23	  });
24	  if (!server) throw new Error("Not found");
25	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
26	  return { user, server };
27	}
28	
29	async function hasInflightJob(serverId: string): Promise<boolean> {
30	  const pending = await db.job.count({
31	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
32	  });
33	  return pending > 0;
34	}
35	
36	// ---------- 1. Scheduled backups ----------
37	
38	/**
39	 * Enable/disable recurring backups and set the cadence. When enabling we do NOT
40	 * touch `lastAutoBackup` — a null/stale value simply lets the sweep run the
41	 * first backup on its next pass.
42	 */
43	export async function setBackupSchedule(
44	  serverId: string,
45	  enabled: boolean,
46	  intervalHours: number
47	): Promise<{ error?: string }> {
48	  const { user, server } = await ownedServer(serverId);
49	
50	  if (enabled && !BACKUP_INTERVAL_CHOICES.includes(intervalHours as any)) {
51	    return { error: "Choose a valid backup interval." };
52	  }
53	
54	  await db.server.update({
55	    where: { id: server.id },
56	    data: {
57	      autoBackup: enabled,
58	      backupIntervalHours: enabled ? intervalHours : null,
59	    },
60	  });
61	  await db.auditLog.create({
62	    data: {
63	      userId: user.id,
64	      action: "server.backup_schedule",
65	      detail: enabled ? `${serverId} every ${intervalHours}h` : `${serverId} disabled`,
66	    },
67	  });
68	  revalidatePath(`/dashboard/servers/${serverId}`);
69	  return {};
70	}
71	
72	// ---------- 2. Reinstall to a different OS ----------
73	
74	/**
75	 * Switch the server to a different OS image and reinstall. This ERASES all data:
76	 * the worker's REINSTALL handler destroys the VM and re-provisions it from
77	 * `Server.osTemplateId`, so we persist the new template BEFORE enqueuing.
78	 */
79	export async function reinstallToOs(
80	  serverId: string,
81	  osTemplateId: string
82	): Promise<{ error?: string }> {
83	  const { user, server } = await ownedServer(serverId);
84	
85	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
86	    return { error: "Server must be running or stopped to reinstall." };
87	  }
88	
89	  const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
90	  if (!os?.active) return { error: "That operating system isn't available." };
91	  if (os.id === server.osTemplateId) {
92	    return { error: "This server is already running that operating system." };
93	  }
94	  if (server.plan.ramMB < os.minRamMB) {
95	    return { error: `${os.name} needs at least ${os.minRamMB / 1024} GB RAM — your plan has ${server.plan.ramMB / 1024} GB.` };
96	  }
97	  if (server.plan.diskGB < os.minDiskGB) {
98	    return { error: `${os.name} needs at least ${os.minDiskGB} GB disk — your plan has ${server.plan.diskGB} GB.` };
99	  }
100	
101	  if (await hasInflightJob(serverId)) {
102	    return { error: "Another operation is already in progress on this server." };
103	  }
104	
105	  // A reinstall destroys and re-clones the VM (same vmid). Its disks — including
106	  // any block-storage volume disk (vm-<vmid>-disk-N) — are purged with it. A
107	  // *detached* volume still keeps its disk under this vmid (Proxmox "unused"), so
108	  // purge wipes it too. Refuse while ANY volume is pinned to this server so the
109	  // customer must delete it (which cleanly destroys just that disk) first.
110	  const pinnedVolumes = await db.volume.count({ where: { serverId } });
111	  if (pinnedVolumes > 0) {
112	    return {
113	      error: `Delete the ${pinnedVolumes} block-storage volume${pinnedVolumes === 1 ? "" : "s"} on this server before reinstalling — a reinstall wipes the whole disk, and volume data can't be recovered.`,
114	    };
115	  }
116	
117	  // Persist the target OS first so the REINSTALL handler (which re-provisions
118	  // from Server.osTemplateId) rebuilds onto the new image, then enqueue.
119	  await db.server.update({ where: { id: server.id }, data: { osTemplateId: os.id } });
120	  await db.job.create({ data: { type: "REINSTALL", serverId } });
121	  await db.auditLog.create({
122	    data: {
123	      userId: user.id,
124	      action: "server.reinstall_os",
125	      detail: `${serverId} -> ${os.slug} (was ${server.osTemplate.slug})`,
126	    },
127	  });
128	  revalidatePath(`/dashboard/servers/${serverId}`);
129	  return {};
130	}
131	
132	// ---------- 3. Resize-down ----------
133	
134	/**
135	 * Move a server to a SMALLER (cheaper) plan. CPU/RAM can shrink freely, but the
136	 * disk can NOT shrink on the hypervisor, so we require the target plan's disk to
137	 * be >= the current plan's disk (the worker's RESIZE handler hard-fails a shrink
138	 * otherwise). A prorated credit for the price difference over the remaining term
139	 * is returned to the wallet.
140	 */
141	export async function resizeServerDown(
142	  serverId: string,
143	  newPlanId: string
144	): Promise<{ error?: string }> {
145	  const { user, server } = await ownedServer(serverId);
146	
147	  const newPlan = await db.plan.findUnique({ where: { id: newPlanId } });
148	  if (!newPlan?.active) return { error: "Plan not available." };
149	  if (newPlan.id === server.planId) return { error: "Server is already on this plan." };
150	  if (!["RUNNING", "STOPPED"].includes(server.status)) return { error: "Server is busy." };
151	
152	  // This action is downgrades only — upgrades go through resizeServer().
153	  if (newPlan.priceCents >= server.plan.priceCents) {
154	    return { error: "This is not a smaller plan — use the upgrade flow instead." };
155	  }
156	  // Disk can't shrink destructively; block the move rather than lose data.
157	  // Compares PLAN disks on purpose: any purchased `extraDiskGB` is additive to
158	  // both the old and the new plan and is preserved verbatim across the resize, so
159	  // "new plan disk >= old plan disk" is exactly the condition for "effective disk
160	  // does not shrink". Nothing here ever writes extraDiskGB.
161	  if (newPlan.diskGB < server.plan.diskGB) {
162	    return {
163	      error: `Disk can't shrink — ${newPlan.name} has a ${newPlan.diskGB} GB disk but your server uses ${server.plan.diskGB} GB. Pick a smaller plan whose disk is at least ${server.plan.diskGB} GB.`,
164	    };
165	  }
166	
167	  if (await hasInflightJob(serverId)) {
168	    return { error: "Another operation is already in progress on this server." };
169	  }
170	
171	  // Credit at the SAME effective rate the upgrade path charges at (term discount
172	  // and promo applied) over the SAME remaining duration — every month left on
173	  // `expiresAt`, uncapped, exactly as lib/resize.ts charges for.
174	  //
175	  // The old maths credited the raw LIST-price delta, so it refunded more than the
176	  // customer had ever paid (they bought at the term-discounted, promo-reduced
177	  // price). Pricing both directions through lib/proration.ts fixed the RATE, but
178	  // this line then capped the DURATION at one term while the upgrade side did not,
179	  // which broke the round trip the other way: a customer whose stacked "Renew now"
180	  // had pushed `expiresAt` 36 months out on a 12-month term paid $544.32 to
181	  // upgrade Starter -> Max and got only $181.44 back coming straight down, so the
182	  // platform pocketed $362.88 of months they had genuinely paid for. `expiresAt`
183	  // never advances without payment, so all of those months are owed back. The cap
184	  // argument has been removed from `remainingMonths` outright — the two directions
185	  // now cannot express different durations.
186	  let creditCents = 0;
187	  if (!server.isFree && server.expiresAt) {
188	    creditCents = prorateDowngradeCreditCents({
189	      fromMonthlyCents: server.plan.priceCents,
190	      toMonthlyCents: newPlan.priceCents,
191	      termMonths: server.termMonths,
192	      monthsRemaining: remainingMonths(server.expiresAt, Date.now()),
193	    });
194	  }
195	
196	  await db.$transaction([
197	    ...(creditCents > 0
198	      ? [
199	          db.user.update({
200	            where: { id: server.userId },
201	            data: { balanceCents: { increment: creditCents } },
202	          }),
203	          db.walletTransaction.create({
204	            data: {
205	              userId: server.userId,
206	              amountCents: creditCents,
207	              description: `Downgrade to ${newPlan.name} (prorated credit) — ${server.hostname}`,
208	            },
209	          }),
210	        ]
211	      : []),
212	    // Record the amount credited on the job so the worker's RESIZE handler can
213	    // REVERSE it (re-debit `payload.prorateCents` from the wallet) if the resize
214	    // terminally fails — the credit is committed here, before the job runs.
215	    // INTEGRATION NEEDED: worker must honour payload.prorateCents/direction.
216	    db.job.create({
217	      data: {
218	        type: "RESIZE",
219	        serverId,
220	        payload: { planId: newPlan.id, prorateCents: creditCents, direction: "down" } as any,
221	      },
222	    }),
223	    db.auditLog.create({
224	      data: {
225	        userId: user.id,
226	        action: "server.resize_down",
227	        detail: `${serverId} -> ${newPlan.slug} credit=${creditCents}`,
228	      },
229	    }),
230	  ]);
231	
232	  revalidatePath(`/dashboard/servers/${serverId}`);
233	  return {};
234	}
