export async function orderGameServer(gamePlanId: string): Promise<Result> {
  const user = await requireUser();

  // Feature flag: game servers can be switched off platform-wide.
  if (!(await getSettingBool("feature_game_servers", true))) {
    return { error: "Game servers aren't available right now." };
  }

  // Game servers are Server rows too, so they count toward the per-user cap
  // (`max_servers_per_user`, default 10; 0 = unlimited).
  const cap = await getSettingInt("max_servers_per_user", 10);
  if (cap > 0) {
    const owned = await db.server.count({ where: { userId: user.id, status: { notIn: ["DELETING"] } } });
    if (owned >= cap) {
      return { error: `You've reached your limit of ${cap} server${cap === 1 ? "" : "s"}.` };
    }
  }

  const gp = await db.gamePlan.findUnique({
    where: { id: gamePlanId },
    include: { basePlan: true },
  });
  if (!gp || !gp.active) return { error: "That game plan isn't available." };
  if (!gp.basePlan?.active) return { error: "Provisioning is temporarily unavailable for this game." };
  if (!GAME_FAMILIES.includes(gp.gameFamily as GameFamily)) {
    return { error: "Unknown game family." };
  }

  // Resolve the game image: the tier's own OsTemplate, else any active image for
  // this game family. A game server can't provision without an image.
  let osTemplateId = gp.osTemplateId;
  if (osTemplateId) {
    const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
    if (!os?.active) osTemplateId = null;
  }
  if (!osTemplateId) {
    const os = await db.osTemplate.findFirst({
      where: { family: gp.gameFamily, category: "APPLICATION", active: true },
      orderBy: { sortOrder: "asc" },
    });
    if (!os) return { error: "No game image is configured for this game yet." };
    osTemplateId = os.id;
  }

  const chargeCents = gp.priceCents;
  if (user.balanceCents < chargeCents) {
    return { error: "Insufficient balance. Top up your wallet first." };
  }

  // Oversell guard — the VPS order path enforces this but game orders skipped it,
  // letting game servers commit host RAM past capacity. Check the base plan's
  // footprint before charging or enqueuing a PROVISION that can't be scheduled.
  const capacity = await capacityCheck(gp.basePlanId);
  if (!capacity.ok) return { error: capacity.reason ?? "The host is at capacity right now. Please try again shortly." };

  const hostname = `${gp.gameFamily}-${rand()}`;

  let server;
  try {
    server = await db.$transaction(async (tx) => {
      await debitWallet(tx, user.id, chargeCents);
      await tx.walletTransaction.create({
        data: {
          userId: user.id,
          amountCents: -chargeCents,
          description: `Game server: ${gp.name} (${gp.gameFamily})`,
        },
      });
      const s = await tx.server.create({
        data: {
          name: hostname,
          hostname,
          userId: user.id,
          planId: gp.basePlanId,
          gamePlanId: gp.id,
          osTemplateId: osTemplateId!,
          termMonths: gp.termMonths,
          wantsDedicatedIp: false,
          expiresAt: addMonths(new Date(), gp.termMonths),
        },
      });
      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
      return s;
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) {
      return { error: "Insufficient balance. Top up your wallet first." };
    }
    throw e;
  }

  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "gameserver.order",
      detail: `${server.id} game=${gp.gameFamily} tier=${gp.name}`,
    },
  });
  redirect(`/dashboard/servers/${server.id}`);
