/**
 * The one discount formula: round(regularCents * (1 - discountPercent/100)).
 *
 * Split out from `promoPriceCents` so proration can price against the percent a
 * server's term was ACTUALLY sold at (Server.termPromoPercent) without inventing a
 * fake `Promo` object to carry the number — and, crucially, without a second copy
 * of this line. Checkout and proration must round identically or an upgrade and its
 * mirror-image downgrade stop cancelling.
 */
export function discountedCents(regularCents: number, discountPercent: number): number {
  return Math.round(regularCents * (1 - discountPercent / 100));
}

/**
 * The genuine first-term price for a regular price under `promo`. This exact value
 * is what checkout charges for the first term — display it verbatim.
 */
export function promoPriceCents(regularCents: number, promo: Promo): number {
  return discountedCents(regularCents, promo.discountPercent);
}

/**
 * The DEEPEST discount this platform has ever run, derived from the catalogue
 * above rather than hard-coded so a new promo tightens it automatically.
 *
 * Used as the conservative fallback rate for a server whose sold rate is genuinely
 * unrecoverable (lib/proration.ts `resolveTermPromoPercent`). "Assume they paid the
 * least we have ever charged" is the only assumption under which a prorated CREDIT
 * is guaranteed to stay below the cash actually collected for those months.
 */
export function deepestPromoPercent(): number {
  return Math.max(LAUNCH_SALE.discountPercent, ...SEASONAL_PROMOS.map((p) => p.discountPercent));
}

