input.content:
/**
 * One-off backfill for `Server.termPromoPercent` (added 2026-07-26).
 *
 * WHY. `prorateDeltaCents` used to default its rate basis to `currentPromo(now)`,
 * so a resize was priced off whatever seasonal promo happened to be running when
 * the customer clicked — letting them upgrade under a 45% basis and downgrade under
 * a 15% one and keep the spread on every remaining month. The fix records the rate
 * each term was ACTUALLY sold at on the server row. Rows that predate the column
 * are NULL, and NULL must never quietly fall back to today's promo, because that is
 * the bug itself. This script fills them from the billing record.
 *
 * HOW, in strict order of evidence. Each row reports which rule fired.
 *
 *   1. free / no expiry      -> 100 (gifted; nothing was sold, nothing prorates)
 *   2. game plan             -> 0   (orderGameServer charges gp.priceCents flat:
 *                                    no term discount, no promo, and renewalCharge
 *                                    renews at that same flat price)
 *   3. INVOICE for the current term -> the percent stated on the document
 *   4. WALLET TRANSACTION for the order -> same, for rows that predate invoicing
 *   5. otherwise             -> the conservative fallback (see below)
 *
 * Rules 3 and 4 read what the customer was genuinely billed. Both an order and a
 * renewal write their description from the same templates the code still uses:
 *   order:   "Order: <Plan> VPS (<hostname>) — <Term> · <Promo> NN% off first term"
 *   renewal: "Renewal: <Plan> VPS (<hostname>) — <Term>"          (no promo, ever)
 * so "NN% off first term" is the sold percent, and a renewal is 0% by definition —
 * lib/promotions.ts guarantees renewals never receive the intro discount. The
 * current term's document is identified by `periodEnd` landing on the server's
 * `expiresAt` (they are written from two separate `new Date()` calls milliseconds
 * apart, hence the tolerance) AND by carrying the hostname, so one user's several
 * servers cannot cross-match.
 *
 * Every derived percent is CROSS-CHECKED arithmetically against the cash actually
 * taken: recompute what that percent implies the charge should have been and
 * compare. A mismatch is reported loudly rather than written silently.
 *
 * THE FALLBACK IS NOT "FULL PRICE". The intuitive conservative guess — assume they
 * paid undiscounted list — is the money-printing direction: a credit is
 * monotonically increasing in the rate basis, so 0% off produces the LARGEST credit
 * this platform can emit, and for anyone who really bought under a deep promo it
 * pays out more cash than they ever handed over. The safe assumption is the
 * opposite: the LEAST we have ever charged (`deepestPromoPercent()`). See
 * lib/proration.ts `resolveTermPromoPercent` for the worked numbers.
 *
 * IDEMPOTENT: only ever touches rows where the column IS NULL. Re-running is a
 * no-op. Pass --apply to write; the default is a dry run.
 *
 *   npx tsx scripts/backfill-term-promo-percent.ts            # dry run
 *   npx tsx scripts/backfill-term-promo-percent.ts --apply    # write
 */

import { db } from "../lib/db";
import { vpsTermPriceCents } from "../lib/billing-terms";
import { deepestPromoPercent, discountedCents } from "../lib/promotions";

const APPLY = process.argv.includes("--apply");

/** Tolerance when matching a billing document's periodEnd to `expiresAt`. */
const PERIOD_MATCH_MS = 60_000;

/** "… · Summer Sale 30% off first term" -> 30. No note at all means full price. */
function promoPercentFromDescription(description: string): number | null {
  const m = /(\d{1,3})%\s*off\s*first\s*term/i.exec(description);
  if (!m) return null;
  const pct = Number(m[1]);
  return Number.isFinite(pct) && pct >= 0 && pct <= 100 ? pct : null;
}

type Resolution = {
  percent: number;
  rule: string;
  evidence: string;
  /** Set when the arithmetic cross-check disagreed with the stated percent. */
  warning?: string;
};

async function resolveServer(s: {
  id: string;
  hostname: string;
  userId: string;
  isFree: boolean;
  expiresAt: Date | null;
  termMonths: number;
  gamePlanId: string | null;
  plan: { name: string; priceCents: number };
  gamePlan: { name: string; priceCents: number } | null;
}): Promise<Resolution> {
  if (s.isFree || !s.expiresAt) {
    return {
      percent: 100,
      rule: "gifted",
      evidence: s.isFree ? "isFree" : "no expiresAt — nothing was sold",
    };
  }

  if (s.gamePlanId) {
    // Flat all-in price, no term discount and no promo on either the order or the
    // renewal. Cross-check against the cash: the order debits exactly priceCents.
    const tx = await db.walletTransaction.findFirst({
      where: { userId: s.userId, description: { startsWith: "Game server:" } },
      orderBy: { createdAt: "desc" },
    });
    const expected = s.gamePlan?.priceCents ?? null;
    const paid = tx ? Math.abs(tx.amountCents) : null;
    return {
      percent: 0,
      rule: "game-plan-flat-price",
      evidence: `gamePlan "${s.gamePlan?.name}" @ ${expected}c, wallet debit ${paid ?? "n/a"}c`,
      warning:
        expected !== null && paid !== null && expected !== paid
          ? `game plan price ${expected}c but ${paid}c was debited`
          : undefined,
    };
  }

  // The billing document that bought the term currently on the clock.
  const lo = new Date(s.expiresAt.getTime() - PERIOD_MATCH_MS);
  const hi = new Date(s.expiresAt.getTime() + PERIOD_MATCH_MS);
  const invoice = await db.invoice.findFirst({
    where: {
      userId: s.userId,
      periodEnd: { gte: lo, lte: hi },
      description: { contains: `(${s.hostname})` },
    },
    orderBy: { createdAt: "desc" },
  });

  const doc = invoice
    ? { kind: "invoice", ref: `#${invoice.number}`, description: invoice.description, cents: invoice.amountCents }
    : await (async () => {
        // Rows that predate invoicing still have the wallet debit, written from the
        // same description template.
        const tx = await db.walletTransaction.findFirst({
          where: {
            userId: s.userId,
            amountCents: { lt: 0 },
            description: { contains: `(${s.hostname})` },
            OR: [{ description: { startsWith: "Order:" } }, { description: { startsWith: "Renewal:" } }],
          },
          orderBy: { createdAt: "desc" },
        });
        return tx
          ? { kind: "wallet-tx", ref: tx.createdAt.toISOString(), description: tx.description, cents: Math.abs(tx.amountCents) }
          : null;
      })();

  if (!doc) {
    return {
      percent: deepestPromoPercent(),
      rule: "FALLBACK-deepest-discount",
      evidence: "no invoice and no wallet transaction names this hostname",
      warning: "rate genuinely unrecoverable — using the conservative floor",
    };
  }

  const stated = promoPercentFromDescription(doc.description);
  const isRenewal = /^Renewal:/i.test(doc.description);
  const percent = stated ?? 0;
  const rule = stated !== null ? `${doc.kind}-promo-note` : isRenewal ? `${doc.kind}-renewal-full-price` : `${doc.kind}-no-promo-note`;

  // Cross-check: what should that percent have cost for the PLAN alone? The
  // document total can legitimately exceed it (a dedicated IP and extra disk are
  // billed at full price on their own lines, and the wallet debit is one number for
  // the lot), so the plan charge is a lower bound on the total, never an equality.
  const regular = vpsTermPriceCents(s.plan.priceCents, s.termMonths);
  const implied = discountedCents(regular, percent);
  const warning =
    doc.cents < implied
      ? `document total ${doc.cents}c is BELOW the ${implied}c that ${percent}% off implies for the plan alone`
      : undefined;

  return {
    percent,
    rule,
    evidence: `${doc.kind} ${doc.ref} "${doc.description}" total ${doc.cents}c (plan at ${percent}% off = ${implied}c of it)`,
    warning,
  };
}

async function main() {
  const servers = await db.server.findMany({
    where: { termPromoPercent: null },
    include: { plan: true, gamePlan: true },
    orderBy: { createdAt: "asc" },
  });

  const total = await db.server.count();
  console.log(`[backfill] ${total} server row(s) total; ${servers.length} with termPromoPercent = NULL`);
  console.log(`[backfill] mode: ${APPLY ? "APPLY (writing)" : "DRY RUN (pass --apply to write)"}`);
  console.log(`[backfill] conservative fallback for unrecoverable rows: ${deepestPromoPercent()}% off\n`);

  const byRule = new Map<string, number>();
  let warnings = 0;
  let written = 0;

  for (const s of servers) {
    const r = await resolveServer(s);
    byRule.set(r.rule, (byRule.get(r.rule) ?? 0) + 1);
    console.log(`  ${s.hostname} (${s.id})`);
    console.log(`      -> ${r.percent}% off   [${r.rule}]`);
    console.log(`         ${r.evidence}`);
    if (r.warning) {
      warnings++;
      console.log(`         !! ${r.warning}`);
    }
    if (APPLY) {
      // Guarded on NULL so a concurrent write (a renewal landing mid-run) wins
      // rather than being clobbered by a backfilled guess.
      const res = await db.server.updateMany({
        where: { id: s.id, termPromoPercent: null },
        data: { termPromoPercent: r.percent },
      });
      written += res.count;
      if (res.count === 0) console.log(`         (skipped: another writer set it first)`);
    }
  }

  console.log(`\n[backfill] by rule:`);
  for (const [rule, n] of [...byRule.entries()].sort()) console.log(`    ${n}  ${rule}`);
  console.log(`[backfill] warnings: ${warnings}`);
  console.log(`[backfill] rows written: ${APPLY ? written : 0}`);

  const stillNull = await db.server.count({ where: { termPromoPercent: null } });
  console.log(`[backfill] rows still NULL after this run: ${stillNull}`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exitCode = 1;
  })
