test("the sold rate is a required input — there is no rate to fall back to", () => {
  const args = { fromMonthlyCents: STARTER, toMonthlyCents: MAX, termMonths: TERM, monthsRemaining: 12 };
  // Deeper discount => smaller delta => smaller charge AND smaller credit. This is
  // the monotonicity the whole arbitrage rested on, kept explicit: it is fine, and
  // safe, precisely because the rate is a property of the ROW, not of the calendar.
  const deep = prorateUpgradeCents({ ...args, termPromoPercent: 45 });
  const shallow = prorateUpgradeCents({ ...args, termPromoPercent: 15 });
  const full = prorateUpgradeCents({ ...args, termPromoPercent: 0 });
  assert.ok(deep < shallow && shallow < full, `${deep} < ${shallow} < ${full}`);

  // And the rate cannot be omitted. TypeScript enforces this at compile time
  // (`termPromoPercent` is required, not optional); at runtime an omitted value
  // resolves through the explicit fallback rather than through the clock.
  const omitted = (prorateUpgradeCents as unknown as (o: typeof args) => number)(args);
  assert.equal(
    omitted,
    prorateUpgradeCents({ ...args, termPromoPercent: deepestPromoPercent() }),
    "a missing rate must resolve to the declared conservative fallback",
  );
});

/**
 * THE 2026-07-26 MONEY BUG, pinned so it cannot come back.
 *
 * `prorateDeltaCents` defaulted `promo` to `currentPromo(now)`. The customer chose
 * the rate for each half of a round trip by choosing the day they clicked, and the
 * promo calendar is published on the marketing pages.
 */
test("promo-window arbitrage: upgrading at 45% and downgrading at 10% is not a business", () => {
  const cyberMonday = currentPromo(new Date("2026-12-01T12:00:00.000Z"));
  const launchSale = currentPromo(new Date("2026-10-05T12:00:00.000Z"));
  assert.equal(cyberMonday.discountPercent, 45, "the deepest window in the catalogue");
  assert.equal(launchSale.discountPercent, 15, "the always-on fallback between seasons");
  assert.equal(deepestPromoPercent(), 45);

  const pair = { termMonths: TERM, monthsRemaining: TERM };

  // ── WHAT THE OLD CODE DID ────────────────────────────────────────────────
  // Each half priced off whatever promo was running on the day it was clicked.
  const upOnCyberMonday = prorateUpgradeCents({
    fromMonthlyCents: STARTER,
    toMonthlyCents: MAX,
    ...pair,
    termPromoPercent: cyberMonday.discountPercent,
  });
  const downOnLaunchSale = prorateDowngradeCreditCents({
    fromMonthlyCents: MAX,
    toMonthlyCents: STARTER,
    ...pair,
    termPromoPercent: launchSale.discountPercent,
  });
  assert.equal(upOnCyberMonday, 38016, "$380.16 charged to go up under the 45% basis");
  assert.equal(downOnLaunchSale, 58752, "$587.52 credited to come back down under the 15% basis");
  assert.equal(
    downOnLaunchSale - upOnCyberMonday,
    20736,
    "$207.36 of minted cash per cycle, for a server that ended the year on the plan it started on",
  );

  // ── WHAT IT DOES NOW ─────────────────────────────────────────────────────
  // Both halves read ONE number off the server row: the rate the term was sold at.
  // The dates above are not inputs to this module any more, so the same customer
  // running the same play nets exactly nothing.
  const up = prorateUpgradeCents({
    fromMonthlyCents: STARTER,
    toMonthlyCents: MAX,
    ...pair,
    termPromoPercent: SOLD_PCT,
  });
  const down = prorateDowngradeCreditCents({
    fromMonthlyCents: MAX,
    toMonthlyCents: STARTER,
    ...pair,
    termPromoPercent: SOLD_PCT,
  });
  assert.equal(up, down, "equal and opposite — both priced against the persisted rate");
  assert.equal(down - up, 0, "the arbitrage is worth exactly zero");
});

test("no pair of promo windows in the catalogue can be arbitraged", () => {
  // The test above pins the worst pair. This one closes the whole surface: for
  // EVERY ordered pair of promos a customer could time the two halves to, the round
  // trip nets zero, because the promo is not what prices either half.
  const windows = [LAUNCH_SALE, ...SEASONAL_PROMOS];
  assert.ok(windows.length >= 10, "the catalogue must still have windows worth timing");
  for (const soldAt of [0, SOLD_PCT, 45, 100]) {
    for (const upWindow of windows) {
      for (const downWindow of windows) {
        // Whatever dates the two halves land on, both calls get `soldAt` — the
        // server row's rate. The window objects are deliberately unused by the
        // pricing: that is the property under test.
        void upWindow;
        void downWindow;
        const up = prorateUpgradeCents({
          fromMonthlyCents: STARTER,
          toMonthlyCents: MAX,
          termMonths: TERM,
          monthsRemaining: 18.5,
          termPromoPercent: soldAt,
        });
        const down = prorateDowngradeCreditCents({
          fromMonthlyCents: MAX,
          toMonthlyCents: STARTER,
          termMonths: TERM,
          monthsRemaining: 18.5,
          termPromoPercent: soldAt,
        });
        assert.equal(
          up - down,
          0,
          `sold at ${soldAt}% off, up under ${upWindow.id}, down under ${downWindow.id}`,
        );
      }
    }
  }
});

test("lib/proration.ts may never read the clock or the promo calendar for a price", () => {
  // The mechanism of the bug, banned structurally. A single `currentPromo(...)` or
  // `new Date()` anywhere in this module reintroduces a rate the customer can pick
  // by picking the day, and every call site inherits it silently.
  const src = readFileSync(join(__dirname, "..", "lib/proration.ts"), "utf8");
  const code = src.replace(/\/\*[\s\S]*?\*\//g, "").replace(/^\s*\/\/.*$/gm, "");
  assert.ok(!code.includes("currentPromo"), "lib/proration.ts must not call currentPromo");
  assert.ok(!code.includes("new Date("), "lib/proration.ts must not construct a date");
  assert.ok(!code.includes("Date.now("), "lib/proration.ts must not read the clock");
  // `now` was the parameter that carried the clock into the pricing. It is gone.
  assert.ok(!/\bnow\?\s*:/.test(code), "prorateDeltaCents must not take an optional `now`");
});

test("an unknown sold rate resolves to the conservative floor, never to today's promo", () => {
  // NULL is what a row that predates Server.termPromoPercent carries.
  assert.equal(resolveTermPromoPercent(null), deepestPromoPercent());
  assert.equal(resolveTermPromoPercent(undefined), deepestPromoPercent());
  assert.equal(resolveTermPromoPercent(30), 30);
  assert.equal(resolveTermPromoPercent(0), 0, "0 is a real rate (a renewal), not 'missing'");
  // A stored value outside 0-100 is a direct multiplier on money; clamp, don't trust.
  assert.equal(resolveTermPromoPercent(-10), 0);
  assert.equal(resolveTermPromoPercent(150), 100);

  // WHY THE FLOOR IS THE DEEPEST DISCOUNT AND NOT FULL PRICE. The intuitive
  // "assume they paid list" is the money-PRINTING direction: a credit is
  // monotonically increasing in the rate basis, so 0% off emits the largest credit
  // this module can produce — larger than the cash a Cyber Monday buyer ever paid.
  const months = TERM;
  const paidAtDeepest = Math.round(
    vpsEffectiveMonthly(MAX, TERM) * (1 - deepestPromoPercent() / 100) * months,
  );
  const creditAtFullPrice = prorateDowngradeCreditCents({
    fromMonthlyCents: MAX,
    toMonthlyCents: STARTER,
    termMonths: TERM,
    monthsRemaining: months,
    termPromoPercent: 0,
  });
  assert.ok(
    creditAtFullPrice > paidAtDeepest,
    `a full-price basis would refund ${creditAtFullPrice}c against the ${paidAtDeepest}c a deepest-promo buyer paid — ` +
      `$${((creditAtFullPrice - paidAtDeepest) / 100).toFixed(2)} of minted cash`,
  );

  // The floor actually chosen keeps the credit under the cash for EVERY rate a
  // customer could really have been sold, which is the property "can never mint
  // money" actually requires.
  const creditAtFloor = prorateDowngradeCreditCents({
    fromMonthlyCents: MAX,
    toMonthlyCents: STARTER,
    termMonths: TERM,
    monthsRemaining: months,
    termPromoPercent: resolveTermPromoPercent(null),
  });
  for (const reallySoldAt of [0, 15, 20, 25, 30, 35, 40, 45]) {
    const reallyPaid = Math.round(
      vpsEffectiveMonthly(MAX, TERM) * (1 - reallySoldAt / 100) * months,
    );
    assert.ok(
      creditAtFloor < reallyPaid,
      `floor credit ${creditAtFloor}c must stay under the ${reallyPaid}c paid by a ${reallySoldAt}%-off buyer`,
    );
  }
});

/**
 * THE OTHER HALF OF THE SAME BUG: a term's rate is one scalar, but months enter the
 * window at different rates — an intro-discounted first term, renewals at full
 * price, and admin gifts at no price at all. `prorateBlendPercent` is what keeps the
 * scalar honest without repricing months that are already paid for.
 */
test("renewing early blends the rate instead of repricing the discounted months", () => {
  // Buy 36 months at the deepest promo, then hit "Renew now" once — which honestly
  // charges FULL price for 36 more months (lib/promotions.ts: renewals never get
  // the intro discount). Overwriting the rate to 0 would re-rate the original 36
  // discounted months to full list, restoring the exact spread this field kills.
  const blended = prorateBlendPercent({
    currentPercent: 45,
    currentMonths: 36,
    addedPercent: 0,
    addedMonths: 36,
  });
  assert.equal(blended, 22.5, "half the window at 45% off, half at full price");
  assert.ok(blended > 0 && blended < 45, "neither half may be repriced to the other's rate");

  // And the blend is value-preserving: crediting 72 months at the blended rate is
  // the same money as crediting each half at its own rate. (This is why the column
  // is a Float — rounding 22.5 to 23 loses $7.20 of the customer's credit here.)
  const creditOverBoth = prorateDowngradeCreditCents({
    fromMonthlyCents: MAX,
    toMonthlyCents: STARTER,
    termMonths: TERM,
    monthsRemaining: 72,
    termPromoPercent: blended,
  });
  const creditEachHalf =
    prorateDowngradeCreditCents({
      fromMonthlyCents: MAX,
      toMonthlyCents: STARTER,
      termMonths: TERM,
      monthsRemaining: 36,
      termPromoPercent: 45,
    }) +
    prorateDowngradeCreditCents({
      fromMonthlyCents: MAX,
      toMonthlyCents: STARTER,
      termMonths: TERM,
      monthsRemaining: 36,
      termPromoPercent: 0,
    });
  assert.equal(creditOverBoth, creditEachHalf, "blending must not move money in either direction");

  // The overwrite that this replaces, measured.
  const overwritten = prorateDowngradeCreditCents({
    fromMonthlyCents: MAX,
    toMonthlyCents: STARTER,
    termMonths: TERM,
    monthsRemaining: 72,
    termPromoPercent: 0,
  });
  assert.equal(
    overwritten - creditOverBoth,
    31104,
    "$311.04 a plain overwrite would have handed back for months bought at 45% off",
  );
});

test("an admin gift adds months that prorate to nothing, and cannot dilute what was paid", () => {
  // adminExtendServer moves `expiresAt` with no payment. Those months are recorded
  // at 100% off, so the credit pot is exactly what it was before the gift.
  const beforeGift = prorateDowngradeCreditCents({
    fromMonthlyCents: MAX,
    toMonthlyCents: STARTER,
    termMonths: TERM,
    monthsRemaining: 12,
    termPromoPercent: SOLD_PCT,
  });
  const gifted = prorateBlendPercent({
    currentPercent: SOLD_PCT,
    currentMonths: 12,
    addedPercent: 100, // 365 gifted days
    addedMonths: (365 * 86400_000) / MS_PER_AVG_MONTH,
  });
  assert.ok(gifted > SOLD_PCT && gifted < 100, `a partial gift lands between the two: ${gifted}`);
  const afterGift = prorateDowngradeCreditCents({
    fromMonthlyCents: MAX,
    toMonthlyCents: STARTER,
    termMonths: TERM,
    monthsRemaining: 12 + (365 * 86400_000) / MS_PER_AVG_MONTH,
    termPromoPercent: gifted,
  });
  assert.ok(
    Math.abs(afterGift - beforeGift) <= 1,
    `a gift must not change the payout: ${beforeGift}c before, ${afterGift}c after`,
  );

  // A gift onto a server with nothing on the clock is 100% gifted end to end, and
  // pays out nothing at all — the unbounded-admin-extend hole, closed.
  const wholly = prorateBlendPercent({
    currentPercent: 0,
    currentMonths: 0,
    addedPercent: 100,
    addedMonths: 12,
  });
  assert.equal(wholly, 100);
  assert.equal(
    prorateDowngradeCreditCents({
      fromMonthlyCents: MAX,
      toMonthlyCents: STARTER,
      termMonths: TERM,
      monthsRemaining: 12,
      termPromoPercent: wholly,
    }),
    0,
    "months nobody paid for must credit exactly nothing",
  );

  // Repeated gifts only ever dilute toward 100 — no number of admin clicks can
  // raise the payout above what was actually bought.
  let pct = SOLD_PCT;
  let months = 12;
  for (let i = 0; i < 20; i++) {
    const prev = pct;
    pct = prorateBlendPercent({ currentPercent: pct, currentMonths: months, addedPercent: 100, addedMonths: 12 });
    months += 12;
    assert.ok(pct >= prev, "each gift must move the rate toward 'gifted', never away from it");
    assert.ok(pct <= 100);
  }
  const afterTwentyGifts = prorateDowngradeCreditCents({
    fromMonthlyCents: MAX,
    toMonthlyCents: STARTER,
    termMonths: TERM,
    monthsRemaining: months,
    termPromoPercent: pct,
  });
  assert.ok(
    Math.abs(afterTwentyGifts - beforeGift) <= 2,
    `240 gifted months must still pay out only the 12 paid ones: ${afterTwentyGifts}c vs ${beforeGift}c`,
  );
});

test("prorateBlendPercent clamps its inputs and never divides by zero", () => {
  assert.equal(prorateBlendPercent({ currentPercent: 30, currentMonths: 0, addedPercent: 0, addedMonths: 0 }), 30);
  assert.equal(prorateBlendPercent({ currentPercent: 30, currentMonths: 12, addedPercent: 0, addedMonths: -5 }), 30);
  assert.equal(prorateBlendPercent({ currentPercent: 150, currentMonths: 5, addedPercent: 150, addedMonths: 5 }), 100);
  assert.equal(prorateBlendPercent({ currentPercent: -50, currentMonths: 5, addedPercent: -50, addedMonths: 5 }), 0);
  for (const pct of [0, 15, 30, 45, 100]) {
    assert.equal(
      prorateBlendPercent({ currentPercent: pct, currentMonths: 7, addedPercent: pct, addedMonths: 9 }),
      pct,
      "blending a rate with itself is a no-op",
    );
  }
});

/**
 * TRIPWIRE on the write sites. The persisted rate is only as good as the code that
 * writes it: a term sold or extended without recording its rate leaves a NULL, and
 * NULL is priced at the conservative floor rather than at what was actually paid.
 */
test("every path that sells, renews or gifts a term records the rate it was sold at", () => {
  const sites: [string, string, string][] = [
    ["lib/order.ts", "termPromoPercent: freeRequested ? 100 : promo.discountPercent", "initial order (shared core)"],
    ["lib/actions.ts", "termPromoPercent: freeRequested ? 100 : promo.discountPercent", "initial order (form action)"],
    ["lib/actions-gameplans.ts", "termPromoPercent: 0", "game plan — flat price, no promo"],
    ["lib/actions.ts", "termPromoPercent: renewedPercent", "renewNow"],
    ["worker/billing.ts", "termPromoPercent: renewedPercent", "auto-renew sweep"],
    ["lib/actions.ts", "termPromoPercent: 100", "admin free grant / set-free"],
  ];
  for (const [file, needle, what] of sites) {
    assert.ok(readNormalized(file).includes(needle), `${file} must record the sold rate for: ${what}`);
  }
  // Both renewal paths must BLEND rather than overwrite, or renewing early
  // silently reprices months still running at an intro discount.
  for (const file of ["lib/actions.ts", "worker/billing.ts"]) {
    assert.ok(
      readNormalized(file).includes("prorateBlendPercent({ currentPercent: resolveTermPromoPercent("),
      `${file} must blend the renewal into the existing rate, not overwrite it`,
    );
  }
  // adminExtendServer moves expiresAt with no payment; the gifted months must be
  // recorded at 100% off or proration pays out months nobody bought.
  assert.ok(
    readNormalized("lib/actions.ts").includes("addedPercent: 100, // gifted: no cash changed hands for these months"),
    "adminExtendServer must record gifted months as sold at 100% off",
  );
});

