  // The duration used to be the thing four call sites had to agree on by
  // convention; the RATE is now the second such thing, and it broke the same way —
  // by defaulting to something the customer could influence. Both server paths read
  // it off the row and both pickers take it as a prop, all under one name, so a
  // divergence is a visible edit rather than a silent default.
  const sites: [string, string][] = [
    ["lib/resize.ts", "termPromoPercent: server.termPromoPercent"],
    ["lib/actions-server-lifecycle.ts", "termPromoPercent: server.termPromoPercent"],
    ["components/customer/ResizePicker.tsx", "termPromoPercent,"],
    ["components/customer/ResizeDown.tsx", "termPromoPercent,"],
  ];
  for (const [file, expected] of sites) {
    const src = readNormalized(file);
