  const page = readNormalized("app/dashboard/servers/[id]/page.tsx");
  const wired = page.split("termPromoPercent={server.termPromoPercent}").length - 1;
  assert.equal(wired, 2, "both ResizePicker and ResizeDown must be given the server's sold rate");
